def run(city, country, days, geocode_json, geocode_text, probe_status, probe_error):
    def clean(x):
        return ' '.join(str(x).split()) if x is not None else ''

    try:
        d = int(days)
    except Exception:
        d = 3
    if d < 1:
        d = 1
    if d > 5:
        d = 5

    lat = None
    lon = None
    resolved_name = ''
    resolved_country = ''
    error = ''

    if isinstance(geocode_json, dict):
        results = geocode_json.get('results')
        if isinstance(results, list) and results:
            first = results[0]
            if isinstance(first, dict):
                lat = first.get('latitude')
                lon = first.get('longitude')
                resolved_name = clean(first.get('name'))
                resolved_country = clean(first.get('country'))
                admin1 = clean(first.get('admin1'))
                parts = [p for p in [resolved_name, admin1, resolved_country] if p]
                if parts:
                    resolved_name = ', '.join(parts)

    if lat is None or lon is None:
        txt = clean(geocode_text)
        if txt:
            error = txt[:200]
        else:
            error = 'No geocoding result found.'

    try:
        lat_f = float(lat) if lat is not None else None
        lon_f = float(lon) if lon is not None else None
    except Exception:
        lat_f = None
        lon_f = None

    forecast_url = ''
    has_location = lat_f is not None and lon_f is not None
    if has_location:
        forecast_url = (
            'https://api.open-meteo.com/v1/forecast?'
            f'latitude={lat_f}&longitude={lon_f}'
            '&current=temperature_2m,apparent_temperature,weather_code,wind_speed_10m'
            f'&daily=temperature_2m_max,temperature_2m_min,precipitation_probability_max,weather_code'
            f'&forecast_days={d}&timezone=auto'
        )

    if probe_status not in (None, '') and str(probe_status) not in ('200', '200.0'):
        probe_note = f'Forecast probe returned status {probe_status}.'
        error = f'{error} {probe_note}'.strip() if error else probe_note
    if probe_error:
        probe_err = clean(probe_error)[:200]
        if probe_err and probe_err not in error:
            error = f'{error} {probe_err}'.strip() if error else probe_err

    return {
        'has_location': has_location,
        'forecast_url': forecast_url,
        'resolved_name': resolved_name,
        'resolved_country': resolved_country,
        'latitude': lat_f,
        'longitude': lon_f,
        'error': error,
        'days': d,
        'probe_status': probe_status
    }

def run(city, country, days, location_found, forecast_json, forecast_text, extract_error, probe_status):
    def clean(x):
        return ' '.join(str(x).split()) if x is not None else ''

    score = 0
    reasons = []
    severe = False
    usable = False

    if location_found:
        score += 2
        usable = True
        reasons.append('City location was resolved.')
    else:
        reasons.append('City location could not be resolved.')

    daily = {}
    current = {}
    if isinstance(forecast_json, dict):
        current = forecast_json.get('current') if isinstance(forecast_json.get('current'), dict) else {}
        daily = forecast_json.get('daily') if isinstance(forecast_json.get('daily'), dict) else {}
        if current:
            score += 1
            reasons.append('Current conditions were returned.')
        if daily:
            score += 1
            reasons.append('Daily forecast was returned.')

    temps = daily.get('temperature_2m_max') if isinstance(daily, dict) else None
    rain = daily.get('precipitation_probability_max') if isinstance(daily, dict) else None
    codes = daily.get('weather_code') if isinstance(daily, dict) else None

    try:
        if isinstance(temps, list) and temps:
            if max([float(x) for x in temps if x is not None]) >= 30:
                severe = True
                reasons.append('Hot conditions are possible.')
        if isinstance(rain, list) and rain:
            if max([float(x) for x in rain if x is not None]) >= 60:
                severe = True
                reasons.append('Rain chances are elevated.')
        if isinstance(codes, list) and codes:
            if any(int(x) in [95, 96, 99] for x in codes if x is not None):
                severe = True
                reasons.append('Thunderstorm codes appear in the forecast.')
    except Exception:
        pass

    if extract_error:
        reasons.append(clean(extract_error)[:180])

    if str(probe_status) not in ('200', '200.0', 'None', '') and not usable:
        reasons.append(f'Forecast endpoint probe status: {probe_status}.')

    verdict = 'ready' if usable else 'needs_retry'
    if severe and usable:
        verdict = 'watch_out'

    return {'score': score, 'verdict': verdict, 'reasons': reasons, 'severe': severe, 'usable': usable}

def run(city, country, days, extract, judge, forecast):
    def clean(x):
        return ' '.join(str(x).split()) if x is not None else ''

    city = clean(city) or 'the city'
    country = clean(country)
    resolved = clean(extract.get('resolved_name')) if isinstance(extract, dict) else ''
    days_n = extract.get('days') if isinstance(extract, dict) else days
    try:
        days_n = int(days_n)
    except Exception:
        days_n = 3

    judge = judge if isinstance(judge, dict) else {}
    forecast = forecast if isinstance(forecast, dict) else {}
    fjson = forecast.get('json') if isinstance(forecast, dict) else None
    error = clean(extract.get('error')) if isinstance(extract, dict) else ''

    current = {}
    daily = {}
    if isinstance(fjson, dict):
        current = fjson.get('current') if isinstance(fjson.get('current'), dict) else {}
        daily = fjson.get('daily') if isinstance(fjson.get('daily'), dict) else {}

    temp_now = current.get('temperature_2m') if isinstance(current, dict) else None
    feels = current.get('apparent_temperature') if isinstance(current, dict) else None
    wind = current.get('wind_speed_10m') if isinstance(current, dict) else None
    code = current.get('weather_code') if isinstance(current, dict) else None

    max_t = daily.get('temperature_2m_max') if isinstance(daily, dict) else []
    min_t = daily.get('temperature_2m_min') if isinstance(daily, dict) else []
    rain = daily.get('precipitation_probability_max') if isinstance(daily, dict) else []
    codes = daily.get('weather_code') if isinstance(daily, dict) else []

    def fmt_num(x, unit=''):
        try:
            if x is None:
                return 'n/a'
            v = float(x)
            if v.is_integer():
                return f'{int(v)}{unit}'
            return f'{v:.1f}{unit}'
        except Exception:
            return 'n/a'

    title_city = resolved or city + (f', {country}' if country else '')
    if judge.get('usable'):
        verdict_word = 'ready'
        if judge.get('verdict') == 'watch_out':
            verdict_word = 'watch_out'
        speech = f'{title_city} is {verdict_word.replace("_", " ")} for the next {days_n} days. Right now it is about {fmt_num(temp_now, "°C")}, with a feel of {fmt_num(feels, "°C")} and wind near {fmt_num(wind, " km/h")}. '
        if judge.get('verdict') == 'watch_out':
            speech += 'The outlook includes weather worth watching.'
        else:
            speech += 'The forecast details are listed in the report.'
    else:
        speech = f'I could not build a reliable weather outlook for {title_city}. The city could not be resolved cleanly, so I need another try.'

    lines = []
    lines.append('# Weather Outlook')
    lines.append('')
    lines.append('## Verdict')
    lines.append(f'- **Status:** {judge.get("verdict", "unknown")}')
    lines.append(f'- **City:** {title_city}')
    lines.append(f'- **Days summarized:** {days_n}')
    lines.append(f'- **Score:** {judge.get("score", 0)}')
    lines.append('')
    lines.append('## Current conditions')
    lines.append(f'- **Temperature:** {fmt_num(temp_now, "°C")}')
    lines.append(f'- **Feels like:** {fmt_num(feels, "°C")}')
    lines.append(f'- **Wind:** {fmt_num(wind, " km/h")}')
    lines.append(f'- **Weather code:** {fmt_num(code)}')
    lines.append('')
    lines.append('## Daily outlook')
    if isinstance(max_t, list) and max_t:
        for i in range(min(days_n, len(max_t))):
            hi = fmt_num(max_t[i], '°C')
            lo = fmt_num(min_t[i] if isinstance(min_t, list) and i < len(min_t) else None, '°C')
            pr = fmt_num(rain[i] if isinstance(rain, list) and i < len(rain) else None, '%')
            wc = fmt_num(codes[i] if isinstance(codes, list) and i < len(codes) else None)
            lines.append(f'- **Day {i+1}:** high {hi}, low {lo}, rain chance {pr}, code {wc}')
    else:
        lines.append('- No daily forecast data was returned.')
    if error:
        lines.append('')
        lines.append('## Notes')
        lines.append(f'- {error}')
        lines.append('- The city could not be resolved cleanly.')
    lines.append('')
    lines.append('## Reasons')
    for r in (judge.get('reasons') or [])[:6]:
        lines.append(f'- {clean(r)}')

    report = '\n'.join(lines)
    return {'speech': speech[:900], 'report': report}
